using System.Text;

namespace Macaron.DependencyInjection.Generator;

internal static class InjectionRenderer
{
    internal static string Render(InjectionDefinition definition)
    {
        var source = new StringBuilder();

        source.AppendLine(
            """
            // <auto-generated />
            #nullable enable

            namespace Macaron.DependencyInjection
            {
                internal static partial class InjectionContextExtensions
                {
            """
        );

        if (definition.TagFields.Length > 0)
        {
            foreach (var field in definition.TagFields.Split('\n'))
            {
                source.AppendLine($"        {field}");
            }

            source.AppendLine();
        }

        source.AppendLine("        internal static void Inject(");
        source.AppendLine($"            this global::Macaron.DependencyInjection.InjectionContext<{definition.ContextTypeName}> {definition.ContextName},");

        var targetModifier = definition.IsValueType ? "ref " : "";
        var parameters = definition.Parameters.Length == 0 ? "" : $", {definition.Parameters}";

        source.AppendLine($"            {targetModifier}{definition.TargetTypeName} {definition.TargetName}{parameters})");
        source.AppendLine("        {");
        source.AppendLine($"            var {definition.ResolverName} = {definition.ContextName}.Resolver;");

        if (definition.DependencyStatements.Length > 0)
        {
            foreach (var statement in definition.DependencyStatements.Split('\n'))
            {
                source.AppendLine($"            {statement}");
            }
        }

        source.AppendLine($"            {definition.TargetName}.{definition.MethodName}({definition.Arguments});");
        source.AppendLine("        }");
        source.AppendLine("    }");
        source.AppendLine("}");

        return source.ToString();
    }
}
